import React, { useEffect, useRef, useState } from "react";

function Generate() {
  const canvasRef = useRef();
  const containerRef = useRef();
  const [imagePaths, setImagePaths] = useState([]);
  const [isFading, setIsFading] = useState(false);
  const [effects, setEffects] = useState({
    grain: true,
    scanlines: true,
    aberration: true,
    glitch: true,
  });
  const position = useRef({ x: 0, y: 0 });
  const offset = useRef({ x: 0, y: 0 });
  const isDragging = useRef(false);
  const animationRef = useRef();

  useEffect(() => {
    const stored = JSON.parse(localStorage.getItem("selectedImages") || "[]").slice(0, 5);
    if (!stored.length) return;
    setImagePaths(stored);
    generateImage(stored);
    return () => cancelAnimationFrame(animationRef.current);
  }, []);

  const generateGrain = (ctx, width, height, intensity = 300, gamma = 1.4) => {
    const grainData = ctx.getImageData(0, 0, width, height);
    const data = grainData.data;
    for (let i = 0; i < data.length; i += 4) {
      const noise = Math.floor(Math.random() * intensity) - intensity / 2;
      data[i] = 255 * Math.pow(Math.min(255, Math.max(0, data[i] + noise)) / 255, 1 / gamma);
      data[i + 1] = 255 * Math.pow(Math.min(255, Math.max(0, data[i + 1] + noise)) / 255, 1 / gamma);
      data[i + 2] = 255 * Math.pow(Math.min(255, Math.max(0, data[i + 2] + noise)) / 255, 1 / gamma);
    }
    ctx.putImageData(grainData, 0, 0);
  };

  const applyScanlines = (ctx, width, height, gap = 3, alpha = 0.15) => {
    ctx.save();
    ctx.fillStyle = `rgba(0,0,0,${alpha})`;
    for (let y = 0; y < height; y += gap) {
      ctx.fillRect(0, y, width, 1);
    }
    ctx.restore();
  };

  const applyChromaticAberration = (ctx, width, height, offset = 2) => {
    const imgData = ctx.getImageData(0, 0, width, height);
    const data = imgData.data;
    const copy = new Uint8ClampedArray(data);

    for (let y = 0; y < height; y++) {
      for (let x = 0; x < width; x++) {
        const i = (y * width + x) * 4;

        const redIndex = ((y * width + Math.min(width - 1, x + offset)) * 4);
        const blueIndex = ((y * width + Math.max(0, x - offset)) * 4);

        data[i] = copy[redIndex];        // Red
        data[i + 2] = copy[blueIndex + 2]; // Blue
      }
    }
    ctx.putImageData(imgData, 0, 0);
  };

  const applyGlitchEffect = (ctx, width, height, lineHeight = 4, shiftAmount = 10) => {
    for (let y = 0; y < height; y += lineHeight * 4) {
      const shift = (Math.random() - 0.5) * shiftAmount;
      const imageData = ctx.getImageData(0, y, width, lineHeight);
      ctx.putImageData(imageData, shift, y);
    }
  };

  const applyPixelate = (canvas, blockSize = 12) => {
    const ctx = canvas.getContext("2d");
    const imageData = ctx.getImageData(0, 0, canvas.width, canvas.height);
    const data = imageData.data;

    for (let y = 0; y < canvas.height; y += blockSize) {
      for (let x = 0; x < canvas.width; x += blockSize) {
        const i = (y * canvas.width + x) * 4;
        const r = data[i];
        const g = data[i + 1];
        const b = data[i + 2];

        for (let dy = 0; dy < blockSize; dy++) {
          for (let dx = 0; dx < blockSize; dx++) {
            const ii = ((y + dy) * canvas.width + (x + dx)) * 4;
            data[ii] = r;
            data[ii + 1] = g;
            data[ii + 2] = b;
          }
        }
      }
    }

    ctx.putImageData(imageData, 0, 0);
    return canvas;
  };

  const thresholdImage = (canvas) => {
    const ctx = canvas.getContext("2d");
    const imageData = ctx.getImageData(0, 0, 1080, 1080);
    const data = imageData.data;

    for (let i = 0; i < data.length; i += 4) {
      const avg = (data[i] + data[i + 1] + data[i + 2]) / 3;
      const val = avg > 128 ? 255 : 0;
      data[i] = data[i + 1] = data[i + 2] = val;
    }

    ctx.putImageData(imageData, 0, 0);
    return canvas;
  };

  const generateImage = (imagePaths) => {
    const canvas = canvasRef.current;
    const ctx = canvas.getContext("2d");
    const width = canvas.width;
    const height = canvas.height;

    ctx.clearRect(0, 0, width, height);

    // Function to get color swatches from an image
    const getColorSwatches = async (imageUrl) => {
      return new Promise((resolve) => {
        const img = new Image();
        img.crossOrigin = "Anonymous";
        img.onload = () => {
          const tempCanvas = document.createElement('canvas');
          const tempCtx = tempCanvas.getContext('2d');
          tempCanvas.width = 100;
          tempCanvas.height = 100;
          tempCtx.drawImage(img, 0, 0, 100, 100);

          const imageData = tempCtx.getImageData(0, 0, 100, 100);
          const pixels = imageData.data;
          const colors = new Set();

          for (let i = 0; i < pixels.length; i += 4) {
            if (pixels[i + 3] > 128) { // Only consider non-transparent pixels
              const color = `rgb(${pixels[i]},${pixels[i + 1]},${pixels[i + 2]})`;
              colors.add(color);
            }
          }

          resolve(Array.from(colors));
        };
        img.src = imageUrl;
      });
    };

    // Function to draw random color shapes
    const drawRandomColorShapes = (colors) => {
      const numShapes = 100; // Number of shapes to draw

      for (let i = 0; i < numShapes; i++) {
        const color = colors[Math.floor(Math.random() * colors.length)];
        const size = Math.random() * 200 + 50; // Random size between 50 and 250
        const x = Math.random() * width;
        const y = Math.random() * height;

        ctx.fillStyle = color;

        // Randomly choose between circle and rectangle
        if (Math.random() > 0.5) {
          ctx.beginPath();
          ctx.arc(x, y, size / 2, 0, Math.PI * 2);
          ctx.fill();
        } else {
          ctx.fillRect(x - size / 2, y - size / 2, size, size);
        }
      }
    };

    // Function to detect image shape and create appropriate crop pieces
    const createCropPieces = (img) => {
      const tempCanvas = document.createElement('canvas');
      const tempCtx = tempCanvas.getContext('2d');
      tempCanvas.width = width;
      tempCanvas.height = height;
      tempCtx.drawImage(img, 0, 0, width, height);

      const imageData = tempCtx.getImageData(0, 0, width, height);
      const pixels = imageData.data;

      // Analyze image to determine if it's more circular or rectangular
      let circularity = 0;
      const centerX = width / 2;
      const centerY = height / 2;
      const radius = Math.min(width, height) / 2;

      for (let y = 0; y < height; y++) {
        for (let x = 0; x < width; x++) {
          const i = (y * width + x) * 4;
          if (pixels[i + 3] > 128) {
            const distance = Math.sqrt(Math.pow(x - centerX, 2) + Math.pow(y - centerY, 2));
            if (distance < radius) {
              circularity++;
            }
          }
        }
      }

      const isCircular = circularity / (width * height) > 0.3;
      const numPieces = 40; // Number of crop pieces
      const pieces = [];

      for (let i = 0; i < numPieces; i++) {
        const size = Math.random() * 100 + 50; // Random size between 50 and 150
        const x = Math.random() * (width - size);
        const y = Math.random() * (height - size);

        if (isCircular && Math.random() < 0.7) {
          // Create circular piece
          pieces.push({
            type: 'circle',
            x: x + size / 2,
            y: y + size / 2,
            radius: size / 2
          });
        } else {
          // Create rectangular piece
          pieces.push({
            type: 'rect',
            x,
            y,
            width: size,
            height: size
          });
        }
      }

      return pieces;
    };

    // Main generation process
    Promise.all(imagePaths.map(loadImage)).then(async (images) => {
      // Get all color swatches from selected images
      const allColors = [];
      for (const img of images) {
        const colors = await getColorSwatches(img.src);
        allColors.push(...colors);
      }

      // Draw random color shapes
      drawRandomColorShapes(allColors);

      // Create and overlay image pieces
      for (const img of images) {
        const pieces = createCropPieces(img);

        pieces.forEach(piece => {
          ctx.save();
          if (piece.type === 'circle') {
            ctx.beginPath();
            ctx.arc(piece.x, piece.y, piece.radius, 0, Math.PI * 2);
            ctx.clip();
          } else {
            ctx.beginPath();
            ctx.rect(piece.x, piece.y, piece.width, piece.height);
            ctx.clip();
          }

          ctx.drawImage(img, 0, 0, width, height);
          ctx.restore();
        });
      }

      // Apply effects
      if (effects.grain) generateGrain(ctx, width, height);
      if (effects.scanlines) applyScanlines(ctx, width, height);
      if (effects.aberration) applyChromaticAberration(ctx, width, height);
      if (effects.glitch) applyGlitchEffect(ctx, width, height);
    });
  };

  const handleDownload = () => {
    const canvas = canvasRef.current;
    const link = document.createElement("a");
    link.download = "generated.png";
    link.href = canvas.toDataURL("image/png");
    link.click();
  };

  const handleRegenerate = () => {
    setIsFading(true);
    setTimeout(() => {
      generateImage(imagePaths);
      setIsFading(false);
    }, 300);
  };

  return (
    <div
      ref={containerRef}
      style={{
        width: "100vw",
        height: "100vh",
        overflow: "hidden",
        position: "relative",
        touchAction: "none",
        cursor: isDragging.current ? "grabbing" : "grab",
        background: "#000",
      }}
    >
      <div style={{
  position: "absolute",
  top: 20,
  left: 20,
  background: "rgba(255,255,255,0.9)",
  padding: "10px 15px",
  borderRadius: "10px",
  zIndex: 10
}}>
  <label>
    <input
      type="checkbox"
      checked={effects.grain}
      onChange={() => setEffects(prev => ({ ...prev, grain: !prev.grain }))}
    /> Grain
  </label>
  <br />
  <label>
    <input
      type="checkbox"
      checked={effects.scanlines}
      onChange={() => setEffects(prev => ({ ...prev, scanlines: !prev.scanlines }))}
    /> Scanlines
  </label>
  <br />
  <label>
    <input
      type="checkbox"
      checked={effects.aberration}
      onChange={() => setEffects(prev => ({ ...prev, aberration: !prev.aberration }))}
    /> Chromatic Aberration
  </label>
  <br />
  <label>
    <input
      type="checkbox"
      checked={effects.glitch}
      onChange={() => setEffects(prev => ({ ...prev, glitch: !prev.glitch }))}
    /> Glitch
  </label>
</div>


      <canvas
        ref={canvasRef}
        width={1080}
        height={1080}
        style={{
          display: "block",
          margin: "0 auto",
          opacity: isFading ? 0.2 : 1,
          transition: "opacity 0.3s ease",
        }}
      />
<div style={{ position: "fixed", top: 20, right: 20, display: "flex", gap: "12px", zIndex: 10 }}>
  <button
    onClick={handleRegenerate}
    style={{
      padding: "8px 16px",
      backgroundColor: "#FFD666",
      border: "none",
      borderRadius: "8px",
      cursor: "pointer",
      fontWeight: "bold",
    }}
  >
    Regenerate
  </button>
  <button
    onClick={handleDownload}
    style={{
      padding: "8px 16px",
      backgroundColor: "#333",
      color: "#fff",
      border: "none",
      borderRadius: "8px",
      cursor: "pointer",
      fontWeight: "bold",
    }}
  >
    Download
  </button>
</div>
    </div>
  );
}

export default Generate;
